export function getLocalGifSource(keyOrUrl?: string): any {
  if (!keyOrUrl || typeof keyOrUrl !== 'string') return null;
  const trimmed = keyOrUrl.trim();
  if (GIF_SOURCES[trimmed]) return GIF_SOURCES[trimmed];
  const base = pathBase(trimmed);
  if (GIF_SOURCES[base]) return GIF_SOURCES[base];
  return null;
}

function pathBase(val: string): string {
  const parts = val.split(/[\\/]/);
  return parts[parts.length - 1] || '';
}
